const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={users:[],departments:[],user:null,view:'home',equipment:[],bookings:[],projects:[],waitlist:[],movements:[],analytics:null,searchResults:null,executionPlan:null,filters:{q:'',department:'',category:''}};
const api=async(url,opts={})=>{const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opts});const data=await r.json();if(!r.ok)throw new Error(data.error||'Something went wrong.');return data};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>String(s||'').split(' ').filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const datePretty=s=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s));
const dateTime=s=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(s));
const localISO=(date,hour)=>{const d=new Date();d.setDate(d.getDate()+date);d.setHours(hour,0,0,0);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:00`;};
const iconFor=c=>({'Development boards':'⌁','Test & measurement':'⌗','AI & compute':'▤','Fabrication':'⌘','Sensors & imaging':'◉','Electronics & tools':'⌁'})[c]||'◇';
function toast(message,error=false){const t=document.createElement('div');t.className=`toast ${error?'error':''}`;t.textContent=message;$('#toasts').append(t);setTimeout(()=>t.remove(),3600);}
async function init(){try{const b=await api('/api/bootstrap');state.users=b.users;state.departments=b.departments;const saved=Number(localStorage.getItem('lablink-user'))||1;state.user=state.users.find(u=>u.id===saved)||state.users[0];await api('/api/demo/session',{method:'POST',body:JSON.stringify({userId:state.user.id})});renderUserOptions();await refresh();render();}catch(e){$('#content').innerHTML=`<div class="empty-state"><strong>LabLink could not connect</strong><p>${esc(e.message)} Check that the local server is running.</p></div>`;}}
function renderUserOptions(){const groups=['student','project_team','faculty','technician','hod','admin'];const labels={student:'Student',project_team:'Project team',faculty:'Faculty',technician:'Lab technician',hod:'HOD / Administrator',admin:'HOD / Administrator'};$('#user-select').innerHTML=groups.map(role=>{const users=state.users.filter(u=>u.role===role);return users.length?`<optgroup label="${labels[role]}">${users.map(u=>`<option value="${u.id}" ${u.id===state.user.id?'selected':''}>${esc(u.name)} · ${esc(u.department)}${role==='student'?` · ${u.study_year}${u.study_year===1?'st':u.study_year===2?'nd':u.study_year===3?'rd':'th'} year`:''}</option>`).join('')}</optgroup>`:''}).join('');$('#user-avatar').textContent=initials(state.user.name);$('#sidebar-profile-avatar').textContent=initials(state.user.name);$('#sidebar-profile-name').textContent=state.user.name;$('#sidebar-profile-meta').textContent=`${labels[state.user.role]||state.user.role}${state.user.role==='student'?` · ${state.user.study_year}${state.user.study_year===1?'st':state.user.study_year===2?'nd':state.user.study_year===3?'rd':'th'} year`:''} · ${state.user.department}`;const reviewer=['faculty','technician','hod','admin'].includes(state.user.role);$('#requests-nav-label').textContent=reviewer?'All requests':'My requests';$('.faculty-nav').classList.toggle('hidden',!reviewer);$('.admin-nav').classList.toggle('hidden',!['hod','admin'].includes(state.user.role));$$('.student-nav').forEach(x=>x.classList.toggle('hidden',state.user.role!=='student'));$$('.tracking-nav').forEach(x=>x.classList.toggle('hidden',!reviewer&&state.user.role!=='student'));}
async function refresh(){const [equipment,bookings,projects,waitlist,movements]=await Promise.all([api(`/api/equipment?userId=${state.user.id}`),api(`/api/bookings?userId=${state.user.id}&role=${state.user.role}`),state.user.role==='student'?api(`/api/projects?userId=${state.user.id}`):Promise.resolve([]),api(`/api/waitlist?userId=${state.user.id}`),api(`/api/equipment/movements?userId=${state.user.id}`)]);state.equipment=equipment;state.bookings=bookings;state.projects=projects;state.waitlist=waitlist;state.movements=movements;$('#request-count').textContent=bookings.length;$('#pending-count').textContent=bookings.filter(b=>b.status==='pending').length;$('#waitlist-count').textContent=waitlist.filter(w=>w.status==='waiting'||w.status==='offered').length;}
function setView(view){stopQrCamera();state.view=view;state.searchResults=null;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const labels={home:'Home',discover:'Discover',planner:'Project planner',projects:'My projects',waitlist:'Equipment waitlist',tracking:'Equipment tracking',bookings:state.user.role==='student'?'My requests':'All requests',review:'Review requests',insights:'Resource insights'};$('#breadcrumb-current').textContent=labels[view]||'Home';$('#sidebar').classList.remove('open');render();}
function render(){if(state.view==='home')renderHome();if(state.view==='discover')renderDiscover();if(state.view==='bookings')renderBookings();if(state.view==='review')renderReview();if(state.view==='insights')renderInsights();if(state.view==='planner')renderPlanner();if(state.view==='projects')renderProjects();if(state.view==='waitlist')renderWaitlist();if(state.view==='tracking')renderTracking();if(state.view==='review'&&['faculty','hod','admin'].includes(state.user.role))$('#content').insertAdjacentHTML('afterbegin','<button class="secondary-button" data-action="export-history">Export review history CSV</button>');}
function renderHome(){
  const firstName=esc(state.user.name.split(' ')[0]);
  const role=state.user.role;
  const greeting=role==='student'||role==='project_team'?'Your next big idea starts here.':'A clearer view of shared campus labs.';
  const description=role==='student'||role==='project_team'
    ?'Find the equipment your project needs, even when it lives in another department. LabLink helps you compare resources and request time with confidence.'
    :'Connect campus resources with the people who need them. Review availability, coordinate requests, and keep shared equipment moving.';
  let steps;
  if(role==='student')steps=[['⌕','Find the right equipment','Search across departments or describe your project for a guided match.','discover','Explore equipment'],['✎','Shape your project plan','Turn your project requirements into an ordered, reviewable timeline.','planner','Plan a project'],['▤','Keep requests on track',`${state.bookings.length} ${state.bookings.length===1?'request':'requests'} in your workspace. See review status and next steps.`,'bookings','View my requests']];
  else if(role==='project_team')steps=[['⌕','Find the right equipment','Search campus resources and check availability before you request a slot.','discover','Explore equipment'],['▤','Keep requests on track',`${state.bookings.length} ${state.bookings.length===1?'request':'requests'} in your workspace. See review status and next steps.`,'bookings','View requests']];
  else if(role==='technician')steps=[['▦','Track equipment','Review movement records and help keep the campus inventory current.','tracking','Open equipment tracking'],['✓','Review requests','See requests that need a staff decision and their allocation details.','review','Review requests'],['⌕','Browse the catalog','Check equipment availability and current condition across departments.','discover','Browse equipment']];
  else if(role==='faculty')steps=[['✓','Review requests','See pending requests with project context and allocation details.','review','Review requests'],['⌕','Browse campus resources','Check availability and help students find suitable equipment.','discover','Browse equipment'],['▦','Track equipment','View recent equipment movements across your labs.','tracking','Open equipment tracking']];
  else steps=[['▥','Review resource insights','See campus utilization and identify equipment that can be shared more effectively.','insights','Open resource insights'],['✓','Review requests','See requests awaiting a decision and their allocation context.','review','Review requests'],['▦','Track equipment','Keep a current view of equipment movement across campus.','tracking','Open equipment tracking']];
  const actions=steps.map(([icon,title,copy,view,label],i)=>`<article class="home-step"><span class="home-step-number">0${i+1}</span><span class="home-step-icon" aria-hidden="true">${icon}</span><h2>${title}</h2><p>${copy}</p><button class="home-card-link" data-action="open-view" data-view="${view}">${label}<span aria-hidden="true">↗</span></button></article>`).join('');
  $('#content').innerHTML=`<div class="home-page">
    <section class="home-hero" aria-labelledby="home-title">
      <div class="home-hero-copy"><div class="eyebrow">LABLINK · CAMPUS RESOURCE EXCHANGE</div><h1 id="home-title">${greeting}</h1><p class="home-welcome">Welcome, ${firstName}. ${description}</p><div class="home-actions"><button class="primary-button home-primary" data-action="open-view" data-view="discover">Explore equipment <span aria-hidden="true">→</span></button>${role==='student'?'<button class="secondary-button" data-action="open-view" data-view="planner">Plan a project</button>':''}</div><div class="home-trust-line"><span class="status-dot"></span> One connected catalog across ${state.departments.length} campus departments</div></div>
      <div class="home-hero-art" aria-hidden="true"><div class="home-art-label">YOUR CAMPUS, CONNECTED</div><div class="home-art-orbit orbit-one"></div><div class="home-art-orbit orbit-two"></div><div class="home-art-core"><span class="home-art-mark">L</span><strong>Ideas meet<br>the right tools.</strong><small>PROJECT → EQUIPMENT → ACCESS</small></div><span class="home-art-node node-one">⌁<small>Build</small></span><span class="home-art-node node-two">◉<small>Measure</small></span><span class="home-art-node node-three">⌘<small>Create</small></span><span class="home-art-node node-four">▤<small>Compute</small></span><div class="home-art-caption">Shared labs. More possibilities.</div></div>
    </section>
    <section class="home-section" aria-labelledby="home-start-title"><div class="home-section-head"><div><div class="eyebrow">A GOOD PLACE TO BEGIN</div><h2 id="home-start-title">What would you like to do?</h2></div><span class="home-section-note">${esc(state.user.department)}</span></div><div class="home-steps">${actions}</div></section>
    <section class="home-footer-panel"><div class="home-footer-icon" aria-hidden="true">✳</div><div><h2>Fair access, built into the process.</h2><p>Every request includes clear availability and allocation context, helping shared resources serve more projects across campus.</p></div><button class="text-button" data-action="fairness">How allocation works <span aria-hidden="true">↗</span></button></section>
  </div>`;
}
function renderProjects(){const idsFor=p=>state.equipment.filter(e=>(p.requirements||[]).includes(e.name)).map(e=>e.id);$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">PROJECT REQUIREMENTS</div><h1>My projects</h1><p>Add or remove the equipment your project needs. These requirements help faculty review requests.</p></div><button class="primary-button" data-action="new-project">＋ New project</button></div>${state.projects.length?state.projects.map(p=>{const selected=idsFor(p);return `<section class="panel" style="margin:14px 0"><div class="section-bar"><div><h2 class="section-title">${esc(p.name)}</h2><span class="hint">Due ${datePretty(p.deadline)}</span></div></div><p>${esc(p.description)}</p><div class="form-field"><label>Required equipment</label><div class="tag-list">${selected.length?selected.map(id=>{const e=state.equipment.find(x=>x.id===id);return `<span class="tag">${esc(e.name)} <button type="button" class="link-button" aria-label="Remove ${esc(e.name)}" data-action="remove-project-equipment" data-project-id="${p.id}" data-equipment-id="${id}">×</button></span>`}).join(''):'<span class="hint">No specific equipment selected.</span>'}</div><div class="inline-actions" style="margin-top:10px"><select aria-label="Choose equipment to add" id="project-equipment-${p.id}"><option value="">Choose equipment to add…</option>${state.equipment.filter(e=>!selected.includes(e.id)).map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.department)}</option>`).join('')}</select><button class="secondary-button" data-action="add-project-equipment" data-project-id="${p.id}" ${selected.length===state.equipment.length?'disabled':''}>Add equipment</button></div></div></section>`}).join(''):'<div class="empty-state"><strong>No projects yet</strong><p>Create a project, then add its required equipment.</p><button class="primary-button" data-action="new-project">＋ Create project</button></div>'}`;}
function stats(){const b=state.bookings;return `<div class="stats-row"><div class="stat-card"><div class="stat-label">Resources across campus <span>◈</span></div><div class="stat-value">${state.equipment.length}<small>in ${state.departments.length} departments</small></div></div><div class="stat-card"><div class="stat-label">My active requests <span>↗</span></div><div class="stat-value">${b.filter(x=>['pending','approved'].includes(x.status)).length}<small>${b.filter(x=>x.status==='pending').length} awaiting review</small></div></div><div class="stat-card"><div class="stat-label">Cross-department access <span>◎</span></div><div class="stat-value">${b.filter(x=>x.equipment_department!==state.user.department).length}<small>requests beyond your department</small></div></div></div>`;}
function equipmentCard(e){
  const equivalent=state.equipment.filter(x=>x.id!==e.id&&(x.equivalent_group&&x.equivalent_group===e.equivalent_group||x.category===e.category));
  const isMatch=state.searchResults?.results?.find(r=>r.id===e.id);
  return `<article class="equipment-card">
    <div class="equipment-top">
      <span class="equip-icon" aria-hidden="true">${iconFor(e.category)}</span>
      <div style="display:flex;gap:5px;align-items:center;">
        ${isMatch ? `<span class="ai-match-badge"><span class="ai-sparkle">✦</span> ${isMatch.match ? (80 + Math.min(18, isMatch.match * 5)) + '% Match' : 'AI Match'}</span>` : ''}
        <span class="badge ${e.availability!=='Available now'?'warn':''}">${esc(e.availability)}</span>
      </div>
    </div>
    <span class="dept-pill">${esc(e.department_code || e.department)} · ${esc(e.location)}</span>
    <h3>${esc(e.name)}</h3>
    <div class="equipment-category">${esc(e.category)} · ${esc(e.department)}</div>
    <p class="equip-description">${esc(e.description)}</p>
    <div class="equip-meta">
      <div>⌖ ${esc(e.location)}</div>
      <div title="${esc(e.specs)}">◫ ${esc(e.specs)}</div>
    </div>
    <div class="equipment-category">${e.available_units}/${e.total_units} units free now · Condition: ${esc(({available:'Available',in_use:'In Use',under_maintenance:'Under Maintenance',under_inspection:'Under Inspection'})[e.condition_status]||'Available')} · max ${e.max_hours}h</div>
    ${e.training_requirements?.length?`<div class="equipment-category" style="color:#9c6514;font-weight:600;">${state.user.role==='student'?(e.training_eligible?'✓ Access for 3rd- and 4th-year students':`⚠ ${esc(e.access_reason||'Only 3rd- and 4th-year students can access this item.')}`):e.training_eligible===true?'✓ Mandatory training complete':e.training_eligible===false?'<span class="safety-warning" role="status">⚠ Required safety training is not recorded.</span>':'⚠ Student safety verification required'}</div>${state.user.role==='student'?'':e.training_requirements.map(r=>`<div class="equipment-category">${r.completed?'✓':'○'} ${esc(r.name)}${r.requires_supervision?' · faculty supervision at checkout':''}</div>`).join('')}`:e.training_required?'<div class="equipment-category safety-warning" role="status">⚠ Required safety training is not recorded.</div>':''}
    ${e.restrictions?`<div class="equipment-category">Restrictions: ${esc(e.restrictions)}</div>`:''}
    ${equivalent.length?`<div class="equipment-category">Equivalent alternatives: ${equivalent.map(x=>esc(x.name)+' ('+esc(x.department)+')').join(', ')}</div>`:''}
    <div class="tag-list">${e.tags.slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>
    <div class="card-bottom">
      <span class="units">${e.total_units} ${e.total_units===1?'unit':'units'}</span>
      <span class="inline-actions">${['technician','admin'].includes(state.user.role)?`<button class="link-button" data-action="condition-manage" data-id="${e.id}">Manage condition</button><button class="link-button" data-action="condition-report" data-type="fault" data-id="${e.id}">Report fault</button>`:['student','project_team'].includes(state.user.role)?`<button class="link-button" data-action="condition-report" data-type="damage" data-id="${e.id}">Report damage</button>`:['faculty','hod'].includes(state.user.role)?`<button class="link-button" data-action="condition-report" data-type="fault" data-id="${e.id}">Report fault</button>`:''}${['faculty','technician','admin'].includes(state.user.role)?`<button class="link-button" data-action="manage-training" data-id="${e.id}">Safety policy</button><button class="link-button" data-action="verify-training" data-id="${e.id}">Verify training</button>`:''}<button class="link-button" data-action="condition-history" data-id="${e.id}">History</button><button class="link-button" data-action="training-history" data-id="${e.id}">Safety history</button>${!['technician','admin'].includes(state.user.role)?`<button class="link-button" data-action="request" data-id="${e.id}" ${e.operational_status!=='operational'||(state.user.role==='student'&&e.training_eligible===false)?'disabled':''}>Request slot</button>${state.user.role==='student'?`<button class="link-button" data-action="join-waitlist" data-id="${e.id}" ${e.training_eligible===false?'disabled':''}>Join waitlist</button>`:''}`:''}</span>
    </div>
  </article>`;
}
function renderDiscover(){
  const categories=[...new Set(state.equipment.map(e=>e.category))].sort();
  const rows=(state.searchResults?.results||state.equipment.filter(e=>(!state.filters.department||String(e.department_id)===state.filters.department)&&(!state.filters.category||e.category===state.filters.category)&&(!state.filters.q||(e.name+' '+e.description+' '+e.tags+' '+e.department).toLowerCase().includes(state.filters.q.toLowerCase())))).map(row=>({...state.equipment.find(e=>e.id===row.id),...row}));
  const searchMatrix=state.searchResults?`<div class="ai-matrix-card">
    <div class="ai-matrix-head">
      <div>
        <div class="ai-hero-badge"><span class="ai-sparkle">✦</span> ${esc(state.searchResults.mode)}</div>
        <h2 style="font:700 16px Manrope;margin:4px 0 2px;">AI Requirement Extraction & Capability Match</h2>
        <p style="font-size:11px;color:#59645d;margin:0;">${esc(state.searchResults.interpretation)}</p>
      </div>
      <button class="secondary-button" data-action="clear-search" style="font-size:10px;">✕ Clear AI Match</button>
    </div>
    ${state.searchResults.assistantAnswer?`<div class="recommendation"><strong>LabLink assistant</strong><p>${esc(state.searchResults.assistantAnswer)}</p><small class="hint">${esc(state.searchResults.assistantMode)}</small></div>`:''}
    ${state.searchResults.requirements.length?`<div style="margin:10px 0 6px;"><span class="chips-label">Extracted Technical Requirements & Specs:</span><div class="tag-list" style="margin-top:6px;">${state.searchResults.requirements.slice(0,8).map(t=>`<span class="tag" style="background:#def0e4;color:#18593e;font-weight:700;">✦ ${esc(t)}</span>`).join('')}</div></div>`:''}
  </div>`:'';
  const campusDate=new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
  $('#content').innerHTML=`
    <div class="page-head">
      <div>
        <div class="eyebrow">GENAI CAMPUS LABORATORY RESOURCE EXCHANGE</div>
        <h1>Intelligent Project-to-Lab Allocation.</h1>
        <p>Match complex capstone project requirements to specialized equipment across departments, resolving scheduling conflicts with transparent, fairness-based arbitration.</p>
      </div>
      <div class="date-label"><span>◷</span>${campusDate} · Campus workspace</div>
    </div>
    
    <section class="panel lablink-assistant" aria-label="LabLink project matcher and assistant">
      <h3>Ask LabLink</h3>
      <p class="panel-subtitle">Describe your project to match campus equipment, or ask about requirements, departments, booking status, and alternatives. Answers use role-authorized campus data.</p>
      <div class="ai-input-wrap">
        <input id="equipment-search" value="${esc(state.filters.q)}" maxlength="500" placeholder="Describe your project or ask a question…" aria-label="Describe a project or ask LabLink">
        <button class="ai-match-btn" data-action="ai-search">✦ Match equipment</button>
        <button class="secondary-button" data-action="assistant-ask">Ask</button>
      </div>
      <div class="ai-prompt-chips">
        <span class="chips-label">Try a project:</span>
        <button class="prompt-chip" data-prompt="Autonomous edge rover with computer vision, object detection, and 3D printed enclosure">🤖 Edge AI Vision Rover</button>
        <button class="prompt-chip" data-prompt="Smart IoT agricultural greenhouse with wireless microcontrollers, telemetry and climate sensors">🌱 IoT Greenhouse Station</button>
        <button class="prompt-chip" data-prompt="High-speed PCB circuit debugging with 100 MHz oscilloscope and precision soldering">⚡ High-Speed PCB Debug</button>
        <button class="prompt-chip" data-prompt="Precision laser cutting and rapid prototyping enclosure">🔬 Rapid Laser Enclosure</button>
      </div>
      <button class="text-button assistant-policy-link" data-action="fairness">View fairness policy ↗</button>
      <div id="assistant-answer" aria-live="polite"></div>
      ${searchMatrix}
    </section>

    ${stats()}

    <div class="search-panel">
      <span class="search-icon" aria-hidden="true">⌕</span>
      <span style="font-size:11px;font-weight:700;color:#505953;white-space:nowrap;">Manual Filter:</span>
      <select class="filter-select" id="department-filter" aria-label="Filter by department"><option value="">All campus departments</option>${state.departments.map(d=>`<option value="${d.id}" ${String(d.id)===state.filters.department?'selected':''}>${esc(d.name)}</option>`).join('')}</select>
      <select class="filter-select" id="category-filter" aria-label="Filter by category"><option value="">All equipment categories</option>${categories.map(c=>`<option ${c===state.filters.category?'selected':''}>${esc(c)}</option>`).join('')}</select>
      <button class="secondary-button" data-action="reset-filters" style="margin-left:auto;">Reset filters</button>
    </div>

    <div class="toolbar">
      <div class="section-title">${state.searchResults?'✦ AI Recommended Resources ('+rows.length+')':'Campus Laboratories & Workstations ('+rows.length+')'}</div>
      <div class="result-count">Across ${state.departments.length} departments</div>
    </div>
    
    <div class="equipment-grid">
      ${rows.length?rows.map(equipmentCard).join(''):`<div class="empty-state"><strong>No matching resources</strong><p>Try clicking one of the sample AI project prompts above or clearing your filters.</p><button class="secondary-button" data-action="reset-filters">Clear filters</button></div>`}
    </div>
  `;

  $('#equipment-search').addEventListener('input',e=>{state.filters.q=e.target.value;if(!e.target.value){state.searchResults=null;renderDiscover();}});
  $('#equipment-search').addEventListener('keydown',e=>{if(e.key==='Enter'){$('[data-action="ai-search"]')?.click();}});
  $('#department-filter').addEventListener('change',e=>{state.filters.department=e.target.value;renderDiscover();});
  $('#category-filter').addEventListener('change',e=>{state.filters.category=e.target.value;renderDiscover();});
}
function bookingTable(rows,review=false){if(!rows.length)return `<div class="empty-state"><strong>${review?'You’re all caught up.':'No requests yet'}</strong><p>${review?'New student requests will appear here.':'Find equipment that fits your project and request a slot.'}</p>${!review?'<button class="primary-button" data-action="discover">Explore equipment</button>':''}</div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>PROJECT / STUDENT</th><th>EQUIPMENT & DEPARTMENT</th><th>REQUESTED SLOT</th><th>PRIORITY</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map(b=>{const staff=['faculty','hod','admin','technician'].includes(state.user.role),student=state.user.role==='student',actions=[];if(student&&b.status==='approved'){if(['in_progress','collected'].includes(b.usage_status))actions.push('<button class="secondary-button" data-action="tracking">Return equipment</button>');else if(!b.usage_status&&new Date(b.end_at)>Date.now())actions.push('<button class="secondary-button" data-action="tracking">Collect equipment</button>');if(b.proposed_hours!=null)actions.push('<span class="table-sub">Duration change awaiting approval</span>');else if(new Date(b.start_at)>Date.now())actions.push(`<button class="link-button" data-action="duration-change" data-id="${b.id}">Request duration change</button>`);}if(staff&&b.proposed_hours!=null)actions.push(`<button class="secondary-button" data-action="duration-approve" data-id="${b.id}">Approve ${b.proposed_hours}h</button><button class="link-button" data-action="duration-reject" data-id="${b.id}">Decline</button>`);if(staff&&b.usage_status==='no_show_candidate')actions.push(`<button class="danger-button" data-action="verify-no-show" data-id="${b.id}">Verify missed booking</button>`);if(review&&b.status==='pending')actions.push(`<button class="secondary-button" data-action="request-details" data-id="${b.id}">Review details</button>`);return `<tr><td class="table-primary">${review?`<button class="link-button" data-action="request-details" data-id="${b.id}">${esc(b.student)} · ${esc(b.project)}</button>`:esc(b.project)}<span class="table-sub">${esc(review?`${b.project} · ${b.student_department}`:b.purpose)}</span><span class="table-sub">Deadline · ${datePretty(b.deadline)}</span></td><td class="table-primary">${esc(b.equipment)}<span class="table-sub">${esc(b.equipment_department)}</span></td><td>${dateTime(b.start_at)}<span class="table-sub">until ${dateTime(b.end_at)} · est. ${b.estimated_hours||((new Date(b.end_at)-new Date(b.start_at))/3600000)}h</span></td><td><span class="priority">${Math.round(b.priority_score)}/100</span><span class="table-sub" title="${esc(b.fairness_note)}">Fairness score ⓘ</span></td><td><span class="status-pill status-${esc(b.status)}">${esc(b.status)}</span>${b.usage_status==='no_show_candidate'?'<span class="table-sub">Check-in unmatched · unverified</span>':''}${b.review_note?`<span class="table-sub">${esc(b.review_note)}</span>`:''}</td><td>${actions.join(' ')||'—'}</td></tr>`}).join('')}</tbody></table></div>`;}
function renderBookings(){const list=state.bookings.filter(b=>state.user.role!=='student'||b.user_id===state.user.id);$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">REQUEST TRACKER</div><h1>${state.user.role==='student'?'My requests':'Campus requests'}</h1><p>Track booking status, review notes and allocation history.</p></div><button class="primary-button" data-action="discover">＋ Find equipment</button></div>${stats()}<div class="section-bar"><div class="section-title">Booking history <span class="result-count">(${list.length})</span></div><div class="inline-actions"><button class="secondary-button" data-action="export-json">Export JSON</button><button class="secondary-button" data-action="export-csv">Export CSV</button></div></div>${bookingTable(list)}`;}
function renderWaitlist(){if(state.user.role!=='student'){$('#content').innerHTML='<div class="empty-state"><strong>Student waitlist</strong><p>Switch to a student demo profile to view or respond to waitlist offers.</p></div>';return;}const rows=state.waitlist;$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">FAIR ACCESS QUEUE</div><h1>Equipment waitlist</h1><p>Priority uses project deadline, recent access and department demand. Offers are exclusive for 30 minutes; accepted slots still require faculty approval.</p></div><button class="primary-button" data-action="discover">＋ Find equipment</button></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>PROJECT / EQUIPMENT</th><th>PREFERRED SLOT</th><th>PRIORITY</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map(w=>`<tr><td class="table-primary">${esc(w.project)}<span class="table-sub">${esc(w.equipment)} · ${esc(w.department)}</span><span class="table-sub">Due ${datePretty(w.deadline)}</span></td><td>${dateTime(w.offered_start||w.preferred_start)}<span class="table-sub">until ${dateTime(w.offered_end||w.preferred_end)}${w.offer_expires_at?` · expires ${dateTime(w.offer_expires_at)}`:''}</span></td><td><span class="priority">${Math.round(w.priority_score)}/100</span><span class="table-sub" title="${esc(w.fairness_note)}">Fairness rationale ⓘ</span></td><td><span class="status-pill status-${esc(w.status==='accepted_pending_approval'?'pending':w.status==='confirmed'?'approved':w.status)}">${esc(w.status.replaceAll('_',' '))}</span></td><td>${w.status==='offered'?`<div class="inline-actions"><button class="primary-button" data-action="waitlist-accept" data-id="${w.id}">Accept slot</button><button class="danger-button" data-action="waitlist-decline" data-id="${w.id}">Decline</button></div>`:w.booking_id?`<button class="link-button" data-action="open-bookings">View booking</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No waitlist history yet</strong><p>Join a queue from an equipment card when a preferred slot is full.</p><button class="primary-button" data-action="discover">Explore equipment</button></div>`}`;}
function qrSvg(matrix){const size=matrix.length,pad=4,parts=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(matrix[y][x])parts.push(`<rect x="${x+pad}" y="${y+pad}" width="1" height="1"/>`);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size+pad*2} ${size+pad*2}" role="img" aria-label="Equipment QR code" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><g fill="#111">${parts.join('')}</g></svg>`;}
async function showEquipmentQr(id){try{const qr=await api(`/api/equipment/${id}/qr?userId=${state.user.id}`),d=$('#dialog');d.innerHTML=`<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">EQUIPMENT ID</div><h2>${esc(qr.name)}</h2><p>Print this QR and attach it to the registered equipment item.</p></div><div class="qr-preview">${qrSvg(qr.matrix)}</div><p class="qr-code-text">${esc(qr.code)}</p><div class="form-actions"><button class="primary-button" data-action="close">Done</button></div>`;d.showModal();}catch(e){toast(e.message,true);}}
function renderTracking(){const student=state.user.role==='student',staff=['faculty','technician','admin'].includes(state.user.role),approved=state.bookings.filter(b=>b.status==='approved'&&(student?b.user_id===state.user.id:true));const movements=state.movements;$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">QR EQUIPMENT CUSTODY</div><h1>Equipment tracking</h1><p>Verify collection and return against an approved booking. Camera scanning works in supported secure browsers; simulated scanning is available for demos.</p></div></div>${student||staff?`<section class="panel"><h3>${staff?'Supervised QR collection or return':'Scan during collection or return'}</h3><p class="panel-subtitle">${staff?'Choose the student’s approved booking and scan the equipment QR label to supervise collection or return.':'Choose your approved booking and action, then scan the QR label on that equipment.'}</p><div class="form-grid"><div class="form-field"><label for="scan-booking">Approved booking</label><select id="scan-booking" required>${approved.map(b=>`<option value="${b.id}">${esc(b.equipment)} · ${esc(b.project)} · ${dateTime(b.start_at)}</option>`).join('')}</select></div><div class="form-field"><label for="scan-action">Movement</label><select id="scan-action"><option value="collect">Collect equipment</option><option value="return">Return equipment</option></select></div><div class="form-field full"><label for="scan-equipment">Simulated equipment scan</label><select id="scan-equipment">${state.equipment.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.qr_code)}</option>`).join('')}</select></div></div><div class="inline-actions" style="margin-top:12px"><button class="primary-button" data-action="simulate-scan" ${approved.length?'':'disabled'}>Simulate QR scan</button><button class="secondary-button" data-action="camera-scan" ${approved.length?'':'disabled'}>Use camera</button></div><video id="qr-video" class="qr-video hidden" muted playsinline aria-label="Camera view for scanning an equipment QR code"></video><div id="scan-feedback" class="form-help" role="status">${approved.length?'Camera access is requested only after selecting Use camera.':'An approved booking is required before collection or return.'}</div></section>`:`<section class="panel"><h3>Movement history access</h3><p class="panel-subtitle">This role has read access to campus movement records and equipment QR labels.</p></section>`}<div class="section-bar"><div class="section-title">Registered equipment QR labels</div><span class="hint">Unique QR identifier per equipment record</span></div><div class="equipment-grid">${state.equipment.map(e=>`<article class="equipment-card"><div class="equipment-top"><span class="equip-icon">▦</span><span class="badge">${esc(e.qr_code)}</span></div><h3>${esc(e.name)}</h3><div class="equipment-category">${esc(e.department)} · ${esc(e.location)}</div><div class="card-bottom"><span class="units">ID ${e.id}</span><button class="link-button" data-action="show-equipment-qr" data-id="${e.id}">Show QR label</button></div></article>`).join('')}</div><div class="section-bar"><div class="section-title">Movement history</div><span class="hint">${movements.length} recorded events · timestamped and audited</span></div>${movements.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT / PROJECT</th><th>EQUIPMENT</th><th>MOVEMENT</th><th>TIME</th><th>METHOD / STATUS</th></tr></thead><tbody>${movements.map(m=>`<tr><td class="table-primary">${esc(m.student||state.user.name)}<span class="table-sub">${esc(m.project)}</span></td><td>${esc(m.equipment)}<span class="table-sub">${esc(m.qr_code)}</span></td><td>${esc(m.event_type)}</td><td>${dateTime(m.occurred_at)}</td><td>${esc(m.scan_method)}${m.late_return?'<span class="status-pill status-rejected">Late return</span>':''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No equipment movements recorded</strong><p>Successful QR scans will appear here.</p></div>`}`;}
let qrStream=null,qrFrame=0;function stopQrCamera(){if(qrFrame)cancelAnimationFrame(qrFrame);qrFrame=0;if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null;}const video=$('#qr-video');if(video){video.pause();video.srcObject=null;video.classList.add('hidden');}}
async function submitQrMovement(qrCode,scanMethod){const feedback=$('#scan-feedback'),bookingId=Number($('#scan-booking')?.value),booking=state.bookings.find(x=>x.id===bookingId),action=$('#scan-action')?.value;if(!bookingId||!booking){toast('Choose an approved booking first.',true);return;}if(feedback)feedback.textContent='Recording verified equipment movement…';try{const result=await api('/api/equipment/scan',{method:'POST',body:JSON.stringify({userId:booking.user_id,actorId:state.user.id,bookingId,action,qrCode,scanMethod})});await refresh();render();toast(result.action==='collect'?'Equipment collection recorded.':'Equipment return recorded.'+(result.lateReturn?' · late return logged':''));}catch(e){if(feedback)feedback.textContent=e.message;toast(e.message,true);}}
async function startQrCamera(){if(!window.BarcodeDetector||!navigator.mediaDevices?.getUserMedia){$('#scan-feedback').textContent='Camera QR scanning is not supported here. Use the simulated scan control.';return;}try{qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#qr-video');video.srcObject=qrStream;video.classList.remove('hidden');await video.play();const detector=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!qrStream)return;try{const codes=await detector.detect(video);if(codes.length&&codes[0].rawValue){const code=codes[0].rawValue;stopQrCamera();await submitQrMovement(code,'camera');return;}}catch{}qrFrame=requestAnimationFrame(scan);};scan();}catch(e){stopQrCamera();$('#scan-feedback').textContent=`Camera could not start (${e.message}). Use simulated scanning instead.`;}}
function renderReview(){const list=state.bookings.filter(b=>b.status==='pending');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">FACULTY WORKSPACE</div><h1>Review booking requests.</h1><p>Resolve competing requests with project-fit evidence, deadline context, access history, department balance and clear reasons.</p></div><span class="badge ${list.length?'warn':''}">${list.length} awaiting decision</span></div>${stats()}<div class="section-bar"><div class="section-title">Requests needing your review</div><span class="hint">${list.length?'Actions are recorded in the campus audit log':'No pending requests'}</span></div>${bookingTable(list,true)}<div class="section-bar"><div class="section-title">Recently reviewed</div></div>${bookingTable(state.bookings.filter(b=>b.status!=='pending').slice(0,8),true)}`;}
async function renderInsights(){try{state.analytics=await api('/api/analytics');const a=state.analytics,max=Math.max(1,...a.byDepartment.map(x=>x.bookings));$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">CAMPUS OVERVIEW</div><h1>Resources in context.</h1><p>Monitor demand across departments and spot opportunities to make idle equipment more accessible.</p></div><span class="badge">Live campus data</span></div><div class="stats-row"><div class="stat-card"><div class="stat-label">Catalogued equipment <span>◈</span></div><div class="stat-value">${a.equipment.length}</div></div><div class="stat-card"><div class="stat-label">Booking requests <span>↗</span></div><div class="stat-value">${a.equipment.reduce((n,x)=>n+x.bookings+x.pending,0)}<small>all time</small></div></div><div class="stat-card"><div class="stat-label">Departments <span>◎</span></div><div class="stat-value">${state.departments.length}<small>sharing resources</small></div></div></div><div class="analytics-grid"><section class="panel"><h3>Demand by department</h3><p class="panel-subtitle">Student requests grouped by home department</p><div class="bar-list">${a.byDepartment.map(d=>`<div class="bar-row"><span>${esc(d.department)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(d.bookings?4:0,d.bookings/max*100)}%"></div></div><strong>${d.bookings}</strong></div>`).join('')}</div></section><section class="panel"><h3>Recent activity</h3><p class="panel-subtitle">Campus request and project log</p>${a.recent.length?a.recent.map(x=>`<div class="activity-item"><strong>${esc(x.actor||'System')}</strong> · ${esc(x.action.replaceAll('_',' '))}<br><span class="table-sub">${dateTime(x.created_at)}</span></div>`).join(''):'<div class="activity-item">No activity yet. Requests will appear here.</div>'}</section></div><div class="section-bar"><div class="section-title">Equipment demand</div><span class="hint">Approved bookings and pending requests</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>EQUIPMENT</th><th>DEPARTMENT</th><th>UNITS</th><th>APPROVED</th><th>PENDING</th><th>UTILISATION</th></tr></thead><tbody>${a.equipment.map(e=>`<tr><td class="table-primary">${esc(e.name)}<span class="table-sub">${esc(e.category)}</span></td><td>${esc(e.department)}</td><td>${e.total_units}</td><td>${e.bookings}</td><td>${e.pending}</td><td class="util-cell"><span class="progress"><span style="width:${Math.min(100,e.bookings*15)}%"></span></span>${Math.min(100,e.bookings*15)}%</td></tr>`).join('')}</tbody></table></div>`;}catch(e){toast(e.message,true);}}
function showFairness(){const d=$('#dialog');d.innerHTML=`<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">HOW REQUESTS ARE PRIORITISED</div><h2>Fairness you can see.</h2><p>A transparent score helps faculty compare requests. It recommends an order; a human reviewer makes the decision.</p></div><div class="fairness-list"><div class="fairness-row"><span>◷</span><div><strong>Project urgency</strong><p>Deadlines approaching within three weeks raise the score, with the strongest weight for projects due soon.</p></div></div><div class="fairness-row"><span>↻</span><div><strong>Recent individual access</strong><p>Students with recent approved access receive less priority, so opportunity is shared over time.</p></div></div><div class="fairness-row"><span>◎</span><div><strong>Department demand</strong><p>Department-level demand is considered; access to equipment in another department stays open.</p></div></div><div class="fairness-row"><span>✓</span><div><strong>Safety stays a constraint</strong><p>Required training must be recorded before a request can be submitted. Scores never override safety or equipment availability.</p></div></div></div><div class="form-actions"><button class="primary-button" data-action="close">Got it</button></div>`;d.showModal();}
function showRequest(id){
  const e=state.equipment.find(x=>x.id===Number(id));if(!e)return;
  if(state.user.role!=='student'){toast('Switch to a student demo profile to request equipment.',true);return;}
  const d=$('#dialog');d.dataset.equipmentId=e.id;
  if(!state.projects.length){
    d.innerHTML='<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="empty-state"><strong>No project to attach</strong><p>Create a project first so the faculty reviewer can understand your requirements.</p><button class="primary-button" data-action="new-project">＋ Create project</button></div>';
  }else{
    const projectOptions=state.projects.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · due '+datePretty(p.deadline)+'</option>').join('');
    d.innerHTML='<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">INTELLIGENT SLOT REQUEST &amp; FAIRNESS PREVIEW</div><h2>Request '+esc(e.name)+'</h2><p>'+esc(e.department)+' · '+esc(e.location)+(e.senior_only?(e.training_eligible?' · Senior access (3rd/4th year)':' · Only 3rd/4th-year students can access'):(e.training_requirements?.length?(e.training_eligible?' · ✓ Mandatory training verified':' · ⚠ Missing: '+e.missing_training.map(esc).join(', ')):e.training_required?' · ⚠ Verified safety training required':''))+(e.requires_supervision?' · Faculty supervision required':'')+'</p></div><form id="booking-form"><div class="form-grid"><div class="form-field full"><label for="project-select">Your project</label><select id="project-select" required>'+projectOptions+'</select></div><div class="form-field"><label for="start-at">Start time</label><input id="start-at" type="datetime-local" min="'+localISO(0,0)+'" value="'+localISO(1,10)+'" required></div><div class="form-field"><label for="end-at">End time</label><input id="end-at" type="datetime-local" min="'+localISO(0,0)+'" value="'+localISO(1,12)+'" required></div><div class="form-field"><label for="estimated-hours">Estimated equipment use (hours)</label><input id="estimated-hours" type="number" min="0.5" max="8" step="0.5" value="2" required></div><div class="form-field full"><label for="purpose">Task / project requirements</label><textarea id="purpose" minlength="8" maxlength="500" required placeholder="Describe what you need to do with this equipment and how it supports your project..."></textarea><span class="form-help">Recommendations use your task, equipment limits and existing bookings. A reviewer approves your requested slot.</span></div></div><div id="recommendation-slot"></div><div class="form-error" id="form-error"></div><div class="form-actions"><button class="quiet-button" type="button" data-action="close">Cancel</button><button class="primary-button" type="submit">Submit Request for Faculty Approval →</button></div></form>';
    setTimeout(recommendSlot,60);
    $('#start-at')?.addEventListener('change',recommendSlot);
    $('#end-at')?.addEventListener('change',()=>{if($('#start-at').value&&$('#end-at').value){const h=(new Date($('#end-at').value)-new Date($('#start-at').value))/3600000;if(h>0)$('#estimated-hours').value=Math.round(h*2)/2;}recommendSlot();});
    $('#estimated-hours')?.addEventListener('change',()=>{const start=new Date($('#start-at').value),hours=Number($('#estimated-hours').value);if(Number.isFinite(hours)&&hours>0){start.setMinutes(start.getMinutes()+hours*60);const z=n=>String(n).padStart(2,'0');$('#end-at').value=`${start.getFullYear()}-${z(start.getMonth()+1)}-${z(start.getDate())}T${z(start.getHours())}:${z(start.getMinutes())}`;}recommendSlot();});
    $('#project-select')?.addEventListener('change',recommendSlot);
    $('#purpose')?.addEventListener('change',recommendSlot);
  }
  d.showModal();$('#booking-form')?.addEventListener('submit',submitBooking);
}
async function recommendSlot(){
  try{
    const data=await api('/api/bookings/recommend',{method:'POST',body:JSON.stringify({userId:state.user.id,projectId:Number($('#project-select').value),equipmentId:Number($('#dialog').dataset.equipmentId),startAt:$('#start-at').value,endAt:$('#end-at').value,purpose:$('#purpose')?.value||''})});
    const alternatives=data.alternatives.map(a=>'<div class="recommendation-item"><span><strong>'+esc(a.name)+'</strong><small>'+esc(a.department)+' · '+esc(a.location)+'</small></span><span class="match-pill">'+(a.total_units-a.busy)+' units free</span></div>').join('');
    $('#recommendation-slot').innerHTML=`<div class="recommendation"><h2>Suggested session · ${data.duration.recommendedHours}h</h2><p>${esc(data.duration.taskBasis.join(' '))} Choose the estimated-hours field to match the work you expect. Reservations remain subject to reviewer approval.</p></div><div class="score-radial"><div><div class="score-number">${data.priorityScore}/100</div><div style="font-size:10px;font-weight:700;color:#18593e;">PREDICTED FAIRNESS PRIORITY</div></div><div style="font-size:11px;color:#47544b;line-height:1.45;">${esc(data.explanation)}</div></div>${alternatives?'<div class="recommendation" style="margin-top:10px;"><h2>Intelligent Fallback Alternatives</h2><p class="hint">In case of slot contention, these equivalent resources are available:</p><div class="recommendation-results">'+alternatives+'</div></div>':''}`;
  }catch(e){
    $('#recommendation-slot').innerHTML=`<div class="form-error" style="background:#fff4f2;padding:8px 12px;border-radius:6px;border:1px solid #fedbd5;">⚠ ${esc(e.message)}</div>`;
  }
}
async function submitBooking(ev){ev.preventDefault();$('#form-error').textContent='';try{const out=await api('/api/bookings',{method:'POST',body:JSON.stringify({userId:state.user.id,equipmentId:Number($('#dialog').dataset.equipmentId),projectId:Number($('#project-select').value),startAt:$('#start-at').value,endAt:$('#end-at').value,estimatedHours:Number($('#estimated-hours').value),purpose:$('#purpose').value})});$('#dialog').close();await refresh();setView('bookings');toast(`Request sent · fairness score ${out.priorityScore}/100`);}catch(e){$('#form-error').textContent=e.message;}}
function showWaitlistForm(id){const e=state.equipment.find(x=>x.id===Number(id));if(!e||state.user.role!=='student')return;const d=$('#dialog');if(!state.projects.length){d.innerHTML='<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="empty-state"><strong>Create a project first</strong><p>Waitlist priority is calculated from your project deadline and equipment requirements.</p><button class="primary-button" data-action="new-project">＋ Create project</button></div>';d.showModal();return;}d.dataset.equipmentId=e.id;d.innerHTML=`<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">FAIRNESS-BASED WAITLIST</div><h2>Join the queue for ${esc(e.name)}</h2><p>When your preferred time opens, LabLink offers it to one eligible student at a time. Accepting creates a request for faculty review.</p></div><form id="waitlist-form"><div class="form-grid"><div class="form-field full"><label for="waitlist-project">Your project</label><select id="waitlist-project" required>${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)} · due ${datePretty(p.deadline)}</option>`).join('')}</select></div><div class="form-field"><label for="waitlist-start">Preferred start</label><input id="waitlist-start" type="datetime-local" min="${localISO(0,0)}" value="${localISO(1,10)}" required></div><div class="form-field"><label for="waitlist-end">Preferred end</label><input id="waitlist-end" type="datetime-local" min="${localISO(0,0)}" value="${localISO(1,12)}" required></div><div class="form-field full"><label for="waitlist-purpose">How does this slot support your project?</label><textarea id="waitlist-purpose" minlength="8" maxlength="500" required placeholder="Describe the task that needs this equipment..."></textarea></div></div><div id="waitlist-error" class="form-error"></div><div class="form-actions"><button class="quiet-button" type="button" data-action="close">Cancel</button><button class="primary-button">Join fair access queue</button></div></form>`;d.showModal();$('#waitlist-form').addEventListener('submit',async ev=>{ev.preventDefault();const error=$('#waitlist-error');error.textContent='';try{const out=await api('/api/waitlist',{method:'POST',body:JSON.stringify({userId:state.user.id,equipmentId:e.id,projectId:Number($('#waitlist-project').value),preferredStart:$('#waitlist-start').value,preferredEnd:$('#waitlist-end').value,purpose:$('#waitlist-purpose').value})});d.close();await refresh();setView('waitlist');toast(`Added to waitlist · fairness priority ${out.priorityScore}/100`);}catch(x){error.textContent=x.message;}});}
function showProject(){const d=$('#dialog');d.innerHTML=`<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">PROJECT SETUP</div><h2>Tell us what you’re building.</h2><p>Project details help faculty understand deadlines and make better equipment recommendations.</p></div><form id="project-form"><div class="form-grid"><div class="form-field full"><label for="project-name">Project name</label><input id="project-name" required minlength="3" maxlength="100" placeholder="e.g. Smart greenhouse monitor"></div><div class="form-field full"><label for="project-description">What does your project do?</label><textarea id="project-description" required minlength="10" maxlength="1000" placeholder="Describe your project and the equipment, tools or capabilities it needs..."></textarea></div><div class="form-field"><label for="project-deadline">Submission deadline</label><input id="project-deadline" type="date" min="${new Date().toISOString().slice(0,10)}" required></div></div><div class="form-error" id="project-error"></div><div class="form-actions"><button class="quiet-button" type="button" data-action="close">Cancel</button><button class="primary-button">Create project</button></div></form>`;d.showModal();$('#project-form').addEventListener('submit',async ev=>{ev.preventDefault();try{await api('/api/projects',{method:'POST',body:JSON.stringify({userId:state.user.id,name:$('#project-name').value,description:$('#project-description').value,deadline:$('#project-deadline').value})});$('#dialog').close();await refresh();toast('Project created. Search for equipment that fits.');}catch(e){$('#project-error').textContent=e.message;}});}
async function showFacultyReview(id){
  const b=state.bookings.find(x=>x.id===Number(id));if(!b)return;
  let competing=[];
  try{const q=await api('/api/allocation/recommend',{method:'POST',body:JSON.stringify({reviewerId:state.user.id,equipmentId:b.equipment_id,startAt:b.start_at.slice(0,16),endAt:b.end_at.slice(0,16)})});competing=q.recommendations.filter(x=>x.id!==b.id);}catch{}
  const aiVerdict=(b.priority_score>=70)?`<div class="ai-recommend-box"><strong>✦ AI Allocation Recommendation: APPROVE</strong><p>High fairness score (${Math.round(b.priority_score)}/100). Approaching project deadline (${datePretty(b.deadline)}), strong technical alignment, and balanced access history. Recommended for approval within slot capacity.</p></div>`:`<div class="ai-recommend-box" style="background:#fffaf0;border-color:#f1d69d;"><strong style="color:#8f560e;">✦ AI Allocation Recommendation: REVIEW CAREFULLY</strong><p>Fairness score: ${Math.round(b.priority_score)}/100. Lower urgency or prior student access detected. Faculty discretion advised if competing requests exist.</p></div>`;
  const d=$('#dialog');
  d.innerHTML=`<button class="close-modal" data-action="close" aria-label="Close">×</button><div class="modal-head"><div class="eyebrow">FACULTY REQUEST REVIEW & ARBITRATION</div><h2>${esc(b.project)} · ${esc(b.student)}</h2><p>${esc(b.student_department)} · deadline ${datePretty(b.deadline)}</p></div>${aiVerdict}<section class="panel"><h3>Project brief</h3><p>${esc(b.project_description||'No project description provided.')}</p><h3>Requested resource</h3><p><strong>${esc(b.equipment)}</strong> · ${esc(b.equipment_department)} · ${esc(b.location||'')}<br>${esc(b.equipment_specs||'Specifications unavailable')}</p><p>${b.senior_only?'Senior access (3rd/4th year)':b.training_eligible?'Mandatory training verified':b.missing_training?.length?'Missing mandatory training: '+b.missing_training.map(esc).join(', '):'Training not required'}${b.requires_supervision?' · Faculty or technician supervision required at QR checkout':''}${b.restrictions?' · Restrictions: '+esc(b.restrictions):''}</p><h3>Requested use</h3><p>${esc(b.purpose)}<br>${dateTime(b.start_at)} – ${dateTime(b.end_at)}</p><h3>Allocation rationale · ${Math.round(b.priority_score)}/100</h3><p>${esc(b.fairness_note)}</p></section><div class="section-bar"><div class="section-title">Competing requests for this slot</div></div>${competing.length?competing.map(x=>`<div class="activity-item"><strong>${esc(x.student)}</strong> · ${esc(x.project)} · ${Math.round(x.score)}/100 · ${x.recommended?'recommended':'queued'}<br>${esc(x.allocation_reason)}${x.alternative_slots?.length?`<br><strong>Alternative slots:</strong> ${x.alternative_slots.map(s=>esc(s.label)).join(', ')}`:''}</div>`).join(''):'<p class="hint">No other pending request overlaps this slot.</p>'}<div class="form-actions"><button class="danger-button" data-action="reject" data-id="${b.id}">Reject with reason</button><button class="primary-button" data-action="approve" data-id="${b.id}" ${b.training_eligible===false?'disabled title="Mandatory training is incomplete"':''}>Approve request</button></div>`;
  d.showModal();
}
